public boolean isBalancedAndSymmetric(TreeNode root) {
    if (root == null) return true;
    PairResult children = checkMirrorPair(root.left, root.right);
    return children.symmetric
        && children.balancedA
        && children.balancedB
        && Math.abs(children.heightA - children.heightB) <= 1;
}

private static class PairResult {
    final int heightA;
    final int heightB;
    final boolean balancedA;
    final boolean balancedB;
    final boolean symmetric;

    PairResult(int heightA, int heightB, boolean balancedA, boolean balancedB, boolean symmetric) {
        this.heightA = heightA;
        this.heightB = heightB;
        this.balancedA = balancedA;
        this.balancedB = balancedB;
        this.symmetric = symmetric;
    }
}

private PairResult checkMirrorPair(TreeNode a, TreeNode b) {
    if (a == null && b == null) {
        return new PairResult(0, 0, true, true, true);
    }
    if (a == null || b == null || a.val != b.val) {
        return new PairResult(0, 0, false, false, false);
    }

    PairResult outer = checkMirrorPair(a.left, b.right);
    if (!outer.symmetric) {
        return outer;
    }

    PairResult inner = checkMirrorPair(a.right, b.left);
    if (!inner.symmetric) {
        return inner;
    }

    int heightA = 1 + Math.max(outer.heightA, inner.heightA);
    int heightB = 1 + Math.max(outer.heightB, inner.heightB);

    boolean balancedA = outer.balancedA && inner.balancedA
            && Math.abs(outer.heightA - inner.heightA) <= 1;
    boolean balancedB = outer.balancedB && inner.balancedB
            && Math.abs(outer.heightB - inner.heightB) <= 1;

    return new PairResult(heightA, heightB, balancedA, balancedB, true);
}
```

