    private static void dfs(int[][] maze, int row, int col,
                            boolean[][] visited,
                            List<Point> path,
                            List<List<Point>> allPaths) {
        int rows = maze.length, cols = maze[0].length;
        if (row < 0 || row >= rows || col < 0 || col >= cols) return;
        if (maze[row][col] == 1) return;
        if (visited[row][col]) return;

        // valid cell, so we may add it
        visited[row][col] = true;
        path.add(new Point(row, col));

        if (maze[row][col] == 3) {
            // Save a snapshot of the list.
            // Because Point is immutable, a shallow copy is okay.
            List<Point> snapshot = new ArrayList<>(path);
            // If you want absolute safety if Point were mutable:
            // for (Point p : path) snapshot.add(new Point(p.row, p.col));
            allPaths.add(snapshot);
        } else {
            dfs(maze, row - 1, col, visited, path, allPaths);
            dfs(maze, row + 1, col, visited, path, allPaths);
            dfs(maze, row, col - 1, visited, path, allPaths);
            dfs(maze, row, col + 1, visited, path, allPaths);
        }

        // Undo exactly what we did
        path.remove(path.size() - 1);
        visited[row][col] = false;
    }
}

