public class DynamicMaze {
    private static final int INF = 1_000_000;
    private static final int[][] DIRS = {{1,0},{-1,0},{0,1},{0,-1}};
    private static final int TEMP_DISAPPEARS_AT = 3;

    public static int findMinimumSteps(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) return -1;
        int rows = grid.length, cols = grid[0].length;
        int maxTime = rows * cols + TEMP_DISAPPEARS_AT;
        int[][][] memo = new int[rows][cols][maxTime + 1];
        for (int r=0;r<rows;r++) for (int c=0;c<cols;c++) Arrays.fill(memo[r][c], -1);
        int ans = dfs(grid, 0, 0, 0, rows, cols, maxTime, memo);
        return ans >= INF ? -1 : ans;
    }

    private static int dfs(int[][] grid, int r, int c, int t, int rows, int cols, int maxTime, int[][][] memo) {
        if (r == rows-1 && c == cols-1) return 0;
        if (t > maxTime) return INF;
        if (memo[r][c][t] != -1) return memo[r][c][t];

        int best = INF;

        // 4 moves
        for (int[] d : DIRS) {
            int nr = r + d[0], nc = c + d[1];
            best = Math.min(best, tryStep(grid, nr, nc, t, rows, cols, maxTime, memo));
        }
        // wait
        best = Math.min(best, tryStep(grid, r, c, t, rows, cols, maxTime, memo));

        memo[r][c][t] = best;
        return best;
    }

    private static int tryStep(int[][] grid, int nr, int nc, int t, int rows, int cols, int maxTime, int[][][] memo) {
        if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) return INF;
