import java.util.Arrays;

public class Main {
    private static final int INF = 1_000_000;
    private static final int DISAPPEAR_TIME = 3;
    private static final int[][] DIRS = {{-1,0},{1,0},{0,-1},{0,1}};

    public static int findMinimumSteps(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) return -1;
        int rows = grid.length;
        int cols = grid[0].length;

        int maxTime = rows * cols + DISAPPEAR_TIME;
        int[][][] memo = new int[rows][cols][maxTime + 1];
        for (int i=0;i<rows;i++) {
            for (int j=0;j<cols;j++) {
                Arrays.fill(memo[i][j], -1);
            }
        }

        int result = dfs(grid, 0, 0, 0, rows, cols, maxTime, memo);
        return result >= INF ? -1 : result;
    }

    private static int dfs(int[][] grid, int r, int c, int time,
                           int rows, int cols, int maxTime, int[][][] memo) {
        // If this state is not physically possible, fail.
        if (!canOccupy(grid, r, c, time, rows, cols)) {
            return INF;
        }

        if (r == rows - 1 && c == cols - 1) {
            return 0;
        }

        if (time > maxTime) {
            return INF;
        }

        if (memo[r][c][time] != -1) {
            return memo[r][c][time];
        }

        int best = INF;

        // Try moving in 4 directions
        for (int[] d : DIRS) {
            int nr = r + d[0];
            int nc = c + d[1];
            best = Math.min(best, tryNext(grid, nr, nc, time, rows, cols, maxTime, memo));
        }

        // Try waiting in place
        best = Math.min(best, tryNext(grid, r, c, time, rows, cols, maxTime, memo));

        memo[r][c][time] = best;
        return best;
    }

    private static int tryNext(int[][] grid, int r, int c, int time,
                               int rows, int cols, int maxTime, int[][][] memo) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) {
            return INF;
        }

        int nextTime = time + 1;
        if (nextTime > maxTime) {
            return INF;
        }

        if (!canEnter(grid, r, c, nextTime)) {
            return INF;
        }

        int remaining = dfs(grid, r, c, nextTime, rows, cols, maxTime, memo);
        if (remaining >= INF) {
            return INF;
        }
        return 1 + remaining;
    }

    private static boolean canOccupy(int[][] grid, int r, int c, int time, int rows, int cols) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) return false;
        return canEnter(grid, r, c, time);
    }

    private static boolean canEnter(int[][] grid, int r, int c, int time) {
        int cell = grid[r][c];
        if (cell == 1) return false;
        if (cell == 2) return time >= DISAPPEAR_TIME;
        return true; // 0 is open
    }
}
```

