import java.util.Arrays;

public class Solution {
    private static final int INF = 1_000_000;
    private static final int DISAPPEAR_TIME = 3;
    private static final int[][] DIRS = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

    public static int findMinimumSteps(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) {
            return -1;
        }
        int rows = grid.length;
        int cols = grid[0].length;
        int maxTime = rows * cols + DISAPPEAR_TIME;
        int[][][] memo = new int[rows][cols][maxTime + 1];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                Arrays.fill(memo[r][c], -1);
            }
        }
        int ans = dfs(grid, 0, 0, 0, rows, cols, maxTime, memo);
        return ans >= INF ? -1 : ans;
    }

    private static int dfs(int[][] grid, int r, int c, int time,
                           int rows, int cols, int maxTime, int[][][] memo) {
        if (time > maxTime) return INF;
        if (r < 0 || r >= rows || c < 0 || c >= cols) return INF;
        if (!canEnter(grid, r, c, time)) return INF;

        if (r == rows - 1 && c == cols - 1) return 0;
        if (memo[r][c][time] != -1) return memo[r][c][time];

        int best = INF;

        for (int[] d : DIRS) {
            best = Math.min(best, tryStep(grid, r + d[0], c + d[1], time, rows, cols, maxTime, memo));
        }
        best = Math.min(best, tryStep(grid, r, c, time, rows, cols, maxTime, memo));

        memo[r][c][time] = best;
        return best;
    }

    private static int tryStep(int[][] grid, int r, int c, int time,
                               int rows, int cols, int maxTime, int[][][] memo) {
        if (r < 0 || r >= rows || c < 0 || c >= cols) return INF;
        int nextTime = time + 1;
        if (nextTime > maxTime) return INF;
        if (!canEnter(grid, r, c, nextTime)) return INF;

        int sub = dfs(grid, r, c, nextTime, rows, cols, maxTime, memo);
        if (sub >= INF) return INF;
        return 1 + sub;
    }

    private static boolean canEnter(int[][] grid, int r, int c, int time) {
        int cell = grid[r][c];
        if (cell == 1) return false;
        if (cell == 2) return time >= DISAPPEAR_TIME;
        return true;
    }
}
```

