```
import java.util.Arrays;

public class Solution {
    private static final int INF = 1_000_000;
    private static final int TEMP_DISAPPEAR_TIME = 3;
    // {wait, down, up, right, left}
    private static final int[][] MOVES = {
        {0, 0},
        {1, 0},
        {-1, 0},
        {0, 1},
        {0, -1}
    };

    public static int findMinimumSteps(int[][] grid) {
        if (grid == null || grid.length == 0 || grid[0].length == 0) return -1;
        int rows = grid.length;
        int cols = grid[0].length;

        int maxTime = rows * cols + TEMP_DISAPPEAR_TIME;
        int[][][] memo = new int[rows][cols][maxTime + 1];
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                Arrays.fill(memo[r][c], -1);
            }
        }

        int ans = dfs(grid, 0, 0, 0, rows, cols, maxTime, memo);
        return ans >= INF ? -1 : ans;
    }

    private static int dfs(int[][] grid, int r, int c, int time,
                           int rows, int cols, int maxTime, int[][][] memo) {
        if (time > maxTime) return INF;
        if (r < 0 || r >= rows || c < 0 || c >= cols) return INF;

        // We may only occupy a cell if it is open or its temporary block has disappeared.
        if (grid[r][c] == 1) return INF;
        if (grid[r][c] == 2 && time < TEMP_DISAPPEAR_TIME) return INF;

        if (r == rows - 1 && c == cols - 1) return 0;

        if (memo[r][c][time] != -1) return memo[r][c][time];

        int best = INF;

        for (int[] move : MOVES) {
            int nr = r + move[0];
            int nc = c + move[1];
            int nextTime = time + 1;

            if (nextTime > maxTime) continue;
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) continue;
            if (grid[nr][nc] == 1) continue;
            if (grid[nr][nc] == 2 && nextTime < TEMP_DISAPPEAR_TIME) continue;

            int remaining = dfs(grid, nr, nc, nextTime, rows, cols, maxTime, memo);
            if (remaining < INF) {
                best = Math.min(best, 1 + remaining);
            }
        }

        memo[r][c][time] = best;
        return best;
    }
