static int floodSpan(boolean[][] map, int r, int c, int rows, int cols) {
    // Assumes map[r][c] is true.
    // Find horizontal span [left, right] in row r connected to c, mark false, count.
    int left = c;
    while (left > 0 && map[r][left-1]) left--;
    int right = c;
    while (right < cols-1 && map[r][right+1]) right++;
    int count = right - left + 1;
    for (int x=left; x<=right; x++) map[r][x] = false;
    // Recurse to above and below rows within this span.
    if (r > 0) {
       for (int x=left; x<=right; x++) {
          if (map[r-1][x]) count += floodSpan(map, r-1, x, rows, cols);
       }
    }
    if (r+1 < rows) {
       for (int x=left; x<=right; x++) {
          if (map[r+1][x]) count += floodSpan(map, r+1, x, rows, cols);
       }
    }
    return count;
}

