public static int findLargestIsland(boolean[][] map) {
    if (map == null || map.length == 0 || map[0].length == 0) return 0;
    int rows = map.length;
    int cols = map[0].length;
    int largest = 0;
    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (map[r][c]) {
                int size = floodSpan(map, r, c, rows, cols);
                if (size > largest) largest = size;
            }
        }
    }
    return largest;
}

private static int floodSpan(boolean[][] map, int r, int c, int rows, int cols) {
    // Find contiguous horizontal land in row r that is connected to c.
    int left = c;
    while (left > 0 && map[r][left - 1]) left--;
    int right = c;
    while (right < cols - 1 && map[r][right + 1]) right++;

    int size = right - left + 1;
    for (int x = left; x <= right; x++) {
        map[r][x] = false;
    }

    // Any cell connected to this span must be in the row above or below,
    // and its column must be between left and right.
    if (r > 0) {
        for (int x = left; x <= right; x++) {
            if (map[r - 1][x]) {
                size += floodSpan(map, r - 1, x, rows, cols);
            }
        }
    }
    if (r + 1 < rows) {
        for (int x = left; x <= right; x++) {
            if (map[r + 1][x]) {
                size += floodSpan(map, r + 1, x, rows, cols);
            }
        }
    }
    return size;
}
```
